-- Descrizioni prodotto, lotto 2 (26/10/2026): 18 schede con testo generico da 100-180 caratteri
-- (zanzariere, veranda Thule, riscaldatori a gasolio, kit, strisce LED, oscurante Dometic, dongle Victron).
-- Esclusi: le ~32 schede riscritte da pro, le 8 Alcapower del 26/10 e le 17 della migrazione 027.
-- Solo dati gia' presenti nel catalogo (nome, peso, misure, componenti dei kit e prezzi) e conti semplici.
-- I risparmi dei kit sono calcolati sui prezzi del 26/10: se cambiano i prezzi, aggiornare la frase.

update products set description = $$Zanzariera Remis Remicare 2 per la porta scorrevole laterale dei van, misura 1435 x 1250 mm. Chiude il vano porta lasciando passare l'aria, così di notte o nelle soste in campagna puoi tenere aperto senza far entrare zanzare e insetti, e quando non serve si raccoglie di lato senza togliere spazio all'ingresso. Peso 3,8 kg. Prima di ordinare misura la luce della porta scorrevole del tuo van: per il Fiat Ducato X250 e X290 c'è la versione da 1710 x 1250 mm. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio lo facciamo nel nostro centro tecnico.$$ where slug = 'cda-0153-zanzariera-remicare-2-per-van-1435x1250';

update products set description = $$Zanzariera Remis Remicare su misura per la porta scorrevole laterale del Fiat Ducato X250 e X290 (e dei gemelli Citroën Jumper e Peugeot Boxer della stessa serie), misura 1710 x 1250 mm. Chiude tutta l'apertura della porta lasciando passare l'aria, così nelle sere d'estate puoi tenere aperto senza zanzare, e quando non serve si raccoglie di lato. Peso 3,8 kg. Per van con porta più piccola c'è la Remicare 2 da 1435 x 1250 mm. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio lo facciamo nel nostro centro tecnico.$$ where slug = 'cda-0154-zanzariera-remicare-van-ducato-x250-x290';

update products set description = $$Zanzariera completa Carad-RF per la porta d'ingresso della cellula del camper: tieni la porta aperta per far circolare l'aria senza far entrare zanzare, mosche e falene, soprattutto la sera con le luci accese. Viene fornita completa, pronta per il montaggio sul telaio della porta; peso 4,5 kg. Prima di ordinare controlla misura e modello della porta del tuo camper: se hai dubbi mandaci una foto su WhatsApp al 348 990 5455 e ti diciamo se è compatibile. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio lo facciamo nel nostro centro tecnico.$$ where slug = 'cda-0152-zanzariera-porta-carad-rf-completa';

update products set description = $$Veranda Thule 3200 da 2,50 m con cassonetto antracite e telo Uni Grey, pensata per van e camper compatti. Il telo resta protetto dentro il cassonetto durante il viaggio e si apre a manovella in pochi minuti, creando una zona d'ombra davanti alla porta per mangiare fuori o stare al riparo da sole e pioggia leggera. Peso 14,7 kg: va fissata con gli adattatori giusti per il tuo veicolo (a tetto o a parete), da scegliere in base al modello. Se vuoi motorizzarla c'è il Kit Veranda Motorizzata con centralina e telecomando. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio lo facciamo nel nostro centro tecnico.$$ where slug = 'cda-0156-veranda-thule-3200-antracite-250m';

update products set description = $$Borsa Fiamma Mega Bag per riporre teli, pareti laterali e accessori della veranda quando non sono montati. Misure 140 x 27 x 40 cm: abbastanza lunga per i pali e le parti in tela, e tiene tutto insieme e pulito nel gavone invece che sparso tra le altre cose. Peso 1 kg. È compresa anche nel Kit Veranda Motorizzata. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli.$$ where slug = 'cda-0157-fiamma-mega-bag';

update products set description = $$Kit per avere una veranda motorizzata con un solo acquisto: veranda Thule 3200 da 2,30 m con telo Uni Grey, centralina Thule 230 V per il motore con telecomando e borsa Fiamma Mega Bag per teli e accessori. Comprati uno per uno costano 1.038,99 €: nel kit risparmi 70 €. La centralina funziona a 230 V, quindi con il camper collegato alla colonnina o con un inverter adeguato. Peso totale 17,7 kg. Prima di ordinare verifica gli adattatori di fissaggio per il tuo veicolo: li scegliamo insieme in base al modello. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio e il collegamento elettrico li facciamo nel nostro centro tecnico.$$ where slug = 'cda-bundle-0006-kit-veranda-motorizzata';

update products set description = $$Riscaldatore ad aria a gasolio da 2 kW per van, furgonati e camper fino a circa 6 metri: prende il gasolio dal serbatoio del veicolo e scalda la cellula anche da fermi, senza gas e senza attacco alla corrente. Misure 31 x 11,9 x 14,5 cm e peso 2,9 kg, quindi trova posto sotto un sedile o in un gavone. Il pannello di comando non è incluso: serve il PU-5 o il Comfort, venduti a parte; in alternativa ci sono i kit già completi di pannello. Per camper grandi o per l'inverno in montagna c'è la versione da 4 kW. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio, con presa del gasolio e scarico, lo facciamo nel nostro centro tecnico.$$ where slug = 'cda-0144-riscaldatore-a-gasolio-2kw';

update products set description = $$Riscaldatore ad aria a gasolio da 4 kW per camper mansardati, motorhome e per chi usa il camper d'inverno in montagna: prende il gasolio dal serbatoio del veicolo e scalda tutta la cellula anche da fermi, senza gas e senza colonnina. Misure 40,2 x 15,7 x 18,8 cm, peso 5,5 kg. Il pannello di comando non è incluso: serve il PU-5 o il Comfort, venduti a parte; in alternativa ci sono i kit già completi di pannello. Per van e camper piccoli basta la versione da 2 kW. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio, con presa del gasolio e scarico, lo facciamo nel nostro centro tecnico.$$ where slug = 'cda-0145-riscaldatore-a-gasolio-4kw';

update products set description = $$Dongle Victron VE.Direct Bluetooth Smart: si collega alla porta VE.Direct di regolatori solari MPPT, monitor batteria BMV e inverter Victron che non hanno il Bluetooth integrato, e ti fa vedere tutto sullo smartphone con l'app gratuita VictronConnect. Controlli tensione e stato della batteria, quanto stanno producendo i pannelli e lo storico degli ultimi giorni, e puoi cambiare le impostazioni senza aprire il vano tecnico. Peso 50 g. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli.$$ where slug = 'cda-0160-dongle-bluetooth-smart-ve-direct';

update products set description = $$Oscurante a rullo Dometic DB1R, colore bianco crema, per finestre da 480 x 530 mm. Si abbassa e si alza con un gesto e si ferma dove vuoi: tiene fuori la luce al mattino, dà privacy in area di sosta e d'estate riduce il caldo che entra dal vetro. Peso 1,5 kg. Prima di ordinare misura la tua finestra (luce del vetro e spessore della parete): la misura deve corrispondere. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio lo facciamo nel nostro centro tecnico.$$ where slug = 'cda-0168-oscurante-finestra-dometic-db1r-480x530';

update products set description = $$Pannello solare Lilie PNL025, piccolo e leggero: 79 x 19 x 3 cm per 1,4 kg. È adatto a tenere in carica la batteria quando il camper resta fermo per settimane, o come aiuto alla ricarica su un van con pochi consumi, e trova posto anche dove un pannello grande non entra. Per alimentare frigorifero, luci e prese tutti i giorni serve invece un pannello da 150-300 W con regolatore MPPT: nella guida al fotovoltaico trovi come calcolare la potenza giusta. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio lo facciamo nel nostro centro tecnico.$$ where slug = 'cda-0113-pannello-solare-lilie-pnl025';

update products set description = $$Kit toilette da viaggio con tutto quello che serve per partire: WC portatile Fiamma Bi-Pot 30 (acqua pulita 10 litri, acque nere 11 litri), disgregante Super Kem Blue per il serbatoio delle acque nere, RinoGrey per le acque grigie e igienizzante Super Rinse per il risciacquo. Comprati uno per uno costano 158,96 €: nel kit risparmi 15,97 €. È la soluzione più semplice per van e furgonati senza bagno fisso, o come secondo WC in tenda. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli.$$ where slug = 'cda-bundle-0001-kit-toilette-da-viaggio';

update products set description = $$Kit per mettere in ordine il garage del camper: due Garage-Bars da 200 cm con 10 ganci ad occhiello da fissare alle pareti, il Cargo Strap per bloccare i carichi (portata 20 kg) e 4 ganci per cinghie rettangolari. Così bici, casse e taniche restano ferme in curva e in frenata invece di spostarsi nel gavone. Comprati uno per uno costano 196,97 €: nel kit risparmi 17,98 €. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio lo facciamo nel nostro centro tecnico.$$ where slug = 'cda-bundle-0003-kit-garage-da-viaggio';

update products set description = $$Kit per un impianto dell'acqua fisso, semplice e completo: serbatoio da 84 litri in polietilene (38 x 100 x 22 cm), pompa a immersione con valvola da 12 litri al minuto e rubinetto singolo Cristal in ottone con canna abbattibile. È la base per un van o un furgone camperizzato: lavello con acqua corrente e una buona autonomia tra un rifornimento e l'altro. Comprati uno per uno costano 213,97 €: nel kit risparmi 19,98 €. Prima di ordinare misura il vano del serbatoio. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio lo facciamo nel nostro centro tecnico.$$ where slug = 'cda-bundle-0004-kit-impianto-acqua-fissa';

update products set description = $$Kit comfort per il camper su base Fiat Ducato: oscurante isolante Thermoglas Ducato Windscreen per i tre vetri della cabina e zanzariera per porta Moskito Net 64 (due pannelli da 35 x 230 cm). Il Thermoglas tiene fuori il freddo d'inverno e il sole d'estate e dà privacy in sosta, e la parte superiore si apre per scoprire il parabrezza senza smontarlo; la zanzariera ti lascia tenere aperta la porta senza insetti. Comprati uno per uno costano 277,98 €: nel kit risparmi 27,99 €. Prima di ordinare controlla che il tuo camper sia su base Ducato. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli.$$ where slug = 'cda-bundle-0005-kit-comfort-cabina-guida';

update products set description = $$Striscia LED COB Alcapower da 5 metri a 12 V, luce bianca calda 3000 K, 15 W al metro. Con i LED COB la luce è una linea continua, senza i puntini delle strisce tradizionali: è adatta come luce d'ambiente sotto i pensili, lungo il soffitto o nel letto. Larghezza 1 cm e spessore 1,6 mm. Tutti e 5 i metri accesi assorbono circa 75 W, cioè poco più di 6 A dalla batteria: per consumare meno abbinala al dimmer con telecomando. Per una luce più bianca da lavoro c'è la versione 6500 K. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio lo facciamo nel nostro centro tecnico.$$ where slug = 'striscia-led-cob-12v-3000k-5m-927004';

update products set description = $$Striscia LED COB Alcapower da 5 metri a 12 V, luce bianca fredda 6500 K, 15 W al metro. Con i LED COB la luce è una linea continua, senza puntini: è adatta dove serve vedere bene, come piano cucina, gavoni, garage o vano tecnico. Larghezza 1 cm e spessore 1,6 mm. Tutti e 5 i metri accesi assorbono circa 75 W, cioè poco più di 6 A dalla batteria: con il dimmer con telecomando regoli l'intensità e consumi meno. Per una luce più calda e rilassante c'è la versione 3000 K. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli; il montaggio lo facciamo nel nostro centro tecnico.$$ where slug = 'striscia-led-cob-12v-6500k-5m-927006';

update products set description = $$Dimmer Alcapower con telecomando per strisce LED a 12 V: accendi, spegni e regoli l'intensità della luce senza alzarti, per esempio dal letto. Abbassare la luce riduce anche il consumo dalla batteria di servizio. Il dimmer misura 5 x 1,5 x 0,7 cm e si nasconde dietro i mobili; il telecomando 8,6 x 3,6 x 0,8 cm. Adatto alle strisce LED COB Alcapower da 5 metri. Spedizione in tutta Italia o ritiro gratis nella nostra officina di Tivoli.$$ where slug = 'dimmer-strisce-led-telecomando-927057';
